        \mathfrak{g}_{-\alpha}}^{\mathfrak{n}_{-}} {}\oplus{}
      \mathfrak{h} \oplus \overbrace{\bigoplus_{\alpha \in \posroots}
        \mathfrak{g}_{\alpha}}^{\mathfrak{n}_{+}}. \]

