\begin{definition}
    For a root system generated by simple roots $\roots =
    \gen{\set{\alpha_1, \alpha_2, \dotsc, \alpha_r}}$, any element $c =
    s_{\alpha_1} s_{\alpha_2} \dotsb s_{\alpha_r}$ is a \defined{Coxeter
      element}. The ordering of the roots is irrelevant: any such
    product of all simple roots is a Coxeter element. All Coxeter
    elements have the same order, which is the \defined{Coxeter number},
    denoted $h$.
  \end{definition}

